SELECT "loop_user_preferences"."job_id" FROM "loop_user_preferences" WHERE ("loop_user_preferences"."deleted_at" IS NULL AND "loop_user_preferences"."deleted_at" IS NULL AND NOT "loop_user_preferences"."enabled" AND "loop_user_preferences"."job_id" IS NOT NULL AND "loop_user_preferences"."user_id" = '9f08130205624e40ab85054baebf8b9a'::uuid) ORDER BY "loop_user_preferences"."created_at" DESC
SELECT "loop_user_preferences"."enabled" FROM "loop_user_preferences" WHERE ("loop_user_preferences"."deleted_at" IS NULL AND "loop_user_preferences"."deleted_at" IS NULL AND "loop_user_preferences"."job_id" IS NULL AND "loop_user_preferences"."user_id" = '9f08130205624e40ab85054baebf8b9a'::uuid) ORDER BY "loop_user_preferences"."created_at" DESC LIMIT 1
SELECT "loop_jobs"."created_at", "loop_jobs"."updated_at", "loop_jobs"."created_by_id", "loop_jobs"."updated_by_id", "loop_jobs"."deleted_at", "loop_jobs"."id", "loop_jobs"."slug", "loop_jobs"."name", "loop_jobs"."public_name", "loop_jobs"."public_description", "loop_jobs"."prompt", "loop_jobs"."min_role", "loop_jobs"."enabled", "loop_jobs"."is_builtin", "loop_jobs"."dtstart", "loop_jobs"."rrule", "loop_jobs"."tzid" FROM "loop_jobs" WHERE ("loop_jobs"."deleted_at" IS NULL AND "loop_jobs"."deleted_at" IS NULL AND "loop_jobs"."enabled") ORDER BY "loop_jobs"."public_name" ASC
